ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE POLICY TRANSACTIONS_SELECT_OWN ON transactions FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.charge_wallet(P_WALLET UUID, P_AMOUNT INTEGER) RETURNS UUID LANGUAGE PLPGSQL SECURITY DEFINER AS $$ DECLARE V_UID UUID; V_BAL INTEGER; V_ID UUID; BEGIN SELECT auth.uid() INTO V_UID; SELECT balance INTO V_BAL FROM wallets WHERE user_id = V_UID AND id = P_WALLET; IF V_UID IS NULL OR V_BAL IS NULL THEN RAISE EXCEPTION USING MESSAGE = 'NOT_FOUND'; END IF; IF P_AMOUNT <= 0 OR V_BAL < P_AMOUNT THEN RAISE EXCEPTION USING MESSAGE = 'LIMIT_FAIL'; END IF; INSERT INTO transactions (user_id, amount) VALUES (V_UID, P_AMOUNT) RETURNING id INTO V_ID; RETURN V_ID; END $$;
GRANT EXECUTE ON FUNCTION public.charge_wallet(UUID, INTEGER) TO authenticated;
